  feats:{music:'v6, v6-wild y v6-mini',voice:'Voices: tu propia voz, verificada y privada',edit:'reescribe una sección o una línea'},
  specs:[['Modelos','v6 y v6-wild (Pro), v6-mini (Free); v4 a v5.5 retirados'],['Stems','hasta 12 con Stem Splitter'],['Descargas','Free: 7 de por vida, uso personal; Pro: 20/mes; Premier: 60/mes; Premier con Studio: sin límite (oficial, desde el 3 sep 2026)'],['Precio','Pro US$10/mes o US$8 anual; Premier US$30 o US$24 anual (terceros, 9 sep 2026)'],['Derechos','uso comercial en descargas de plan pago; UMG, Sony y SOCAN siguen en litigio']],
  tpl:[{h:'Style box',code:'[género y subgénero], [tempo ~BPM], [ánimo en 2 palabras], [tipo de voz y entrega], [3-4 instrumentos], [carácter de la mezcla], [época sin nombres de artistas]'},{h:'Letra por secciones',code:'[Intro: sparse pads]\n[Verse 1]\n[letra]\n[Pre-Chorus: rising tension]\n[Chorus: fuller drums, wider harmony]\n[letra]\n[Bridge: stripped back, half-time]\n[Final Chorus: key lift]\n[Outro: fade]'}],
